//! Functions generated by macros, and what macros that replaced functions
//! call instead.
//!
//! Expansion results are cached across releases by (file, blob, index). A
//! cached result is reused only while every fact it was computed from still
//! holds: the same definitions for each macro name it looked up, and the same
//! object-like status for each identifier it checked.

use extract::cpp::{self, Lookup, MacroDef, Resolved, TokenKind};
use extract::{Function, Invocation, MacroDefinition};
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::sync::Arc;

/// What a cached expansion depends on.
pub struct Deps {
    looked_up: Vec<String>,
    checked: Vec<String>,
    fingerprint: u64,
}

impl Deps {
    fn new(lookup: &dyn Lookup, looked_up: Vec<String>, checked: Vec<String>) -> Deps {
        let fingerprint = fingerprint(lookup, &looked_up, &checked);
        Deps {
            looked_up,
            checked,
            fingerprint,
        }
    }

    pub fn still_valid(&self, lookup: &dyn Lookup) -> bool {
        fingerprint(lookup, &self.looked_up, &self.checked) == self.fingerprint
    }
}

fn fingerprint(lookup: &dyn Lookup, looked_up: &[String], checked: &[String]) -> u64 {
    let mut h = DefaultHasher::new();
    for name in looked_up {
        name.hash(&mut h);
        let r = lookup.resolve(name);
        r.uncertain.hash(&mut h);
        for d in &r.defs {
            (&d.params, &d.variadic, &d.body, &*d.file, d.arch.as_deref()).hash(&mut h);
        }
    }
    for name in checked {
        (name, lookup.is_object_like(name)).hash(&mut h);
    }
    h.finish()
}

pub struct Generated {
    /// Functions the invocation defines; empty when the expansion cannot be
    /// trusted (see `cpp::Union::complete`).
    pub functions: Vec<Function>,
    pub deps: Deps,
}

/// Expands a top-level invocation in `file` and extracts the functions it defines.
pub fn generate(lookup: &dyn Lookup, inv: &Invocation, file: &Arc<str>) -> Generated {
    let mut text = inv.text.clone();
    if inv.followed_by_brace {
        // The body follows in the source; the expansion is a function header.
        text.push_str(" { }");
    }
    let context: Vec<cpp::Branch> = inv
        .conditions
        .iter()
        .map(|c| (file.clone(), c.block, c.branch))
        .collect();
    let u = cpp::expand_union_in(&text, lookup, &context);
    // Under a condition on something other than CONFIG_* options (say
    // `BITS_PER_LONG == 32` or `__ARCH_WANT_SYS_OLD_SELECT`), whether an
    // architecture's definitions can apply is unknown from the source alone:
    // x86's syscall wrapper never meets a 32-bit-only syscall, for example.
    // Keep only results that use no architecture-specific definition.
    let arch_dependent = inv.conditions.iter().any(|c| !c.config_only);
    let mut functions: Vec<Function> = Vec::new();
    if u.complete {
        // Per distinct function: the variants producing it.
        let mut produced: Vec<(Function, Vec<usize>)> = Vec::new();
        for (i, v) in u.variants.iter().enumerate() {
            if arch_dependent && v.arch.is_some() {
                continue;
            }
            for mut f in extract::functions_in_expansion(&v.tokens).0 {
                f.line = inv.line;
                f.generated_by = Some(inv.text.clone());
                match produced.iter_mut().find(|(g, _)| *g == f) {
                    Some((_, by)) => by.push(i),
                    None => produced.push((f, vec![i])),
                }
            }
        }
        for (mut f, by) in produced {
            f.origin = origin(&u.variants, &by);
            functions.push(f);
        }
    }
    Generated {
        functions,
        deps: Deps::new(lookup, u.looked_up, u.checked),
    }
}

/// Where a generated function comes from, when not every variant of the
/// expansion produces it. The deciding choices are the definitions every
/// producing variant uses and some other variant replaces:
/// - any of them under `arch/`: those architecture headers;
/// - generic ones that other variants replace with an architecture's own:
///   those, marked as applying only where no architecture overrides them;
/// - otherwise the architecture headers the producing variants rely on, or
///   the architectures whose definitions do not produce it.
fn origin(variants: &[cpp::Variant], producing: &[usize]) -> Option<String> {
    if producing.len() == variants.len() {
        return None;
    }
    let others: Vec<usize> = (0..variants.len()).filter(|i| !producing.contains(i)).collect();
    // A choice is a macro and the definition used for it, compared by identity:
    // two definitions in one file (say, both branches of `#ifdef MODULE`) differ.
    let chose = |i: usize, m: &str| variants[i].origins.iter().find(|(om, _)| om == m).map(|(_, d)| d);
    let common: Vec<(&str, &Arc<MacroDef>)> = variants[producing[0]]
        .origins
        .iter()
        .filter(|(m, d)| {
            producing
                .iter()
                .all(|&p| chose(p, m).is_some_and(|pd| Arc::ptr_eq(pd, d)))
        })
        .map(|(m, d)| (m.as_str(), d))
        .collect();
    let replaced_elsewhere = |m: &str, d: &Arc<MacroDef>| {
        others
            .iter()
            .any(|&o| chose(o, m).is_some_and(|od| !Arc::ptr_eq(od, d)))
    };
    let locations = |defs: Vec<&Arc<MacroDef>>| -> Option<String> {
        let mut l: Vec<String> = defs.iter().map(|d| d.location()).collect();
        l.sort();
        l.dedup();
        (!l.is_empty()).then(|| l.join(", "))
    };
    let deciding: Vec<&Arc<MacroDef>> = common
        .iter()
        .filter(|(m, d)| replaced_elsewhere(m, d))
        .map(|(_, d)| *d)
        .collect();
    let arch_deciding: Vec<&Arc<MacroDef>> = deciding.iter().filter(|d| d.arch.is_some()).copied().collect();
    if !arch_deciding.is_empty() {
        return locations(arch_deciding);
    }
    // Generic definitions that other variants replace with an architecture's
    // own: they apply only where no architecture provides one.
    let overridable: Vec<&Arc<MacroDef>> = common
        .iter()
        .filter(|(m, d)| d.arch.is_none() && others.iter().any(|&o| chose(o, m).is_some_and(|od| od.arch.is_some())))
        .map(|(_, d)| *d)
        .collect();
    if let Some(l) = locations(overridable) {
        return Some(format!("{l} (architectures without their own definition)"));
    }
    // Several architectures: name the architecture definitions relied on, or,
    // when generic definitions produce it too, those that do not.
    let producing_arch: Vec<Option<&Arc<MacroDef>>> =
        producing.iter().map(|&i| variants[i].arch_def.as_ref()).collect();
    if !deciding.is_empty() && producing_arch.iter().all(Option::is_none) {
        return locations(deciding);
    }
    if producing_arch.iter().all(Option::is_some) {
        return locations(producing_arch.into_iter().flatten().collect());
    }
    let excluded: Vec<&Arc<MacroDef>> = others
        .iter()
        .filter_map(|&o| variants[o].arch_def.as_ref())
        .filter(|d| !producing_arch.iter().flatten().any(|p| Arc::ptr_eq(p, d)))
        .collect();
    if let Some(l) = locations(excluded) {
        return Some(format!("all except {l}"));
    }
    locations(deciding)
}

/// Names a macro's expansion calls, with whether the macro's own arguments
/// flow into the call. `None` when the expansion cannot be trusted.
pub struct Calls {
    pub calls: Option<Vec<(String, bool)>>,
    pub deps: Deps,
}

const PLACEHOLDER: &str = "__kfh_arg";

/// Resolves one macro name to a fixed definition and everything else through
/// the surrounding scope.
struct Pinned<'a> {
    inner: &'a dyn Lookup,
    name: &'a str,
    def: Arc<MacroDef>,
}

impl Lookup for Pinned<'_> {
    fn resolve(&self, name: &str) -> Resolved {
        if name == self.name {
            Resolved {
                defs: vec![self.def.clone()],
                uncertain: false,
            }
        } else {
            self.inner.resolve(name)
        }
    }

    fn is_object_like(&self, name: &str) -> bool {
        self.inner.is_object_like(name)
    }
}

/// Expands `m` with placeholder arguments and lists the calls in the result.
pub fn calls(lookup: &dyn Lookup, def: Arc<MacroDef>, m: &MacroDefinition) -> Calls {
    let mut args: Vec<String> = (0..m.params.len()).map(|i| format!("{PLACEHOLDER}{i}")).collect();
    if m.variadic.is_some() {
        args.push(format!("{PLACEHOLDER}_va"));
    }
    let pinned = Pinned {
        inner: lookup,
        name: &m.name,
        def,
    };
    let context = pinned.def.branches.clone();
    let u = cpp::expand_union_in(&format!("{}({})", m.name, args.join(", ")), &pinned, &context);
    let deps = Deps::new(
        lookup,
        u.looked_up.iter().filter(|n| **n != m.name).cloned().collect(),
        u.checked.clone(),
    );
    if !u.complete {
        return Calls { calls: None, deps };
    }
    let flows = |toks: &[cpp::Token]| toks.iter().any(|t| t.text.starts_with(PLACEHOLDER));
    let mut out: Vec<(String, bool)> = Vec::new();
    let mut add = |name: &str, flow: bool| match out.iter_mut().find(|(n, _)| n == name) {
        Some(entry) => entry.1 |= flow,
        None => out.push((name.to_string(), flow)),
    };
    for v in &u.variants {
        let t = &v.tokens;
        for i in 0..t.len() {
            if t[i].kind != TokenKind::Ident || t[i].tainted || !t.get(i + 1).is_some_and(|n| n.is("(")) {
                continue;
            }
            let mut depth = 0usize;
            let mut end = i + 1;
            for (j, tok) in t.iter().enumerate().skip(i + 1) {
                if tok.is("(") {
                    depth += 1;
                } else if tok.is(")") {
                    depth -= 1;
                    if depth == 0 {
                        end = j;
                        break;
                    }
                }
            }
            add(&t[i].text, flows(&t[i + 2..end.max(i + 2)]));
        }
        // A macro in one configuration can be a real function in another,
        // like alloc_tag_save; count the macros that were expanded as calls.
        for (name, args) in &v.expanded {
            add(name, flows(args));
        }
    }
    out.sort();
    Calls { calls: Some(out), deps }
}

/// Splits calls into functions the arguments flow into, and other functions.
pub fn classify(calls: &[(String, bool)], is_function: impl Fn(&str) -> bool) -> (Vec<String>, Vec<String>) {
    let mut primary = Vec::new();
    let mut also = Vec::new();
    for (name, flows) in calls {
        if is_function(name) {
            if *flows {
                primary.push(name.clone());
            } else {
                also.push(name.clone());
            }
        }
    }
    (primary, also)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;

    fn def(params: &[&str], variadic: bool, body: &str) -> Arc<MacroDef> {
        Arc::new(MacroDef {
            params: params.iter().map(|p| p.to_string()).collect(),
            variadic: variadic.then(|| "__VA_ARGS__".to_string()),
            body: body.into(),
            file: Arc::from("include/linux/slab.h"),
            line: 10,
            arch: None,
            branches: Vec::new(),
        })
    }

    #[test]
    fn calls_distinguish_where_arguments_flow() {
        // Shaped like kmem_cache_alloc -> alloc_hooks -> alloc_hooks_tag.
        let mut table: HashMap<String, Vec<Arc<MacroDef>>> = HashMap::new();
        table.insert(
            "alloc_hooks".into(),
            vec![def(
                &["_do_alloc"],
                false,
                "({ DEFINE_ALLOC_TAG(_t); alloc_hooks_tag(&_t, _do_alloc); })",
            )],
        );
        table.insert(
            "alloc_hooks_tag".into(),
            vec![def(
                &["_tag", "_do_alloc"],
                false,
                "({ _old = alloc_tag_save(_tag); _res = _do_alloc; alloc_tag_restore(_tag, _old); _res; })",
            )],
        );
        table.insert("DEFINE_ALLOC_TAG".into(), vec![def(&["x"], false, "static int x")]);
        // In this configuration alloc_tag_save is a macro; elsewhere a function.
        table.insert("alloc_tag_save".into(), vec![def(&["t"], false, "NULL")]);
        let m = MacroDefinition {
            name: "kmem_cache_alloc".into(),
            line: 1,
            params: vec![],
            variadic: Some("__VA_ARGS__".into()),
            body: "alloc_hooks(kmem_cache_alloc_noprof(__VA_ARGS__))".into(),
            conditions: vec![],
        };
        let d = def(&[], true, &m.body);
        let c = calls(&table, d, &m);
        let functions = ["kmem_cache_alloc_noprof", "alloc_tag_save", "alloc_tag_restore"];
        let (primary, also) = classify(c.calls.as_ref().unwrap(), |n| functions.contains(&n));
        assert_eq!(primary, ["kmem_cache_alloc_noprof"]);
        assert_eq!(also, ["alloc_tag_restore", "alloc_tag_save"]);
    }

    #[test]
    fn origin_names_the_deciding_definitions() {
        let mut table: HashMap<String, Vec<Arc<MacroDef>>> = HashMap::new();
        let arch_def = |arch: &str, body: &str| {
            Arc::new(MacroDef {
                params: vec!["n".into()],
                variadic: None,
                body: body.into(),
                file: Arc::from(format!("arch/{arch}/include/asm/syscall_wrapper.h")),
                line: 20,
                arch: Some(Arc::from(arch)),
                branches: Vec::new(),
            })
        };
        table.insert(
            "DEF".into(),
            vec![def(&["n"], false, "WRAP(n) static long __do_sys##n(void) { }")],
        );
        table.insert(
            "WRAP".into(),
            vec![
                arch_def("x86", "long __x64_sys##n(void) { } static long __se_sys##n(void) { }"),
                arch_def(
                    "arm64",
                    "long __arm64_sys##n(void) { } static long __se_sys##n(void) { }",
                ),
                def(&["n"], false, "long sys##n(void) { }"),
            ],
        );
        let inv = Invocation {
            name: "DEF".into(),
            text: "DEF(_read)".into(),
            line: 3,
            followed_by_brace: false,
            conditions: vec![],
        };
        let g = generate(&table, &inv, &Arc::from("fs/read_write.c"));
        let got: Vec<(&str, Option<&str>)> = g
            .functions
            .iter()
            .map(|f| (f.name.as_str(), f.origin.as_deref()))
            .collect();
        assert_eq!(
            got,
            [
                ("__x64_sys_read", Some("arch/x86/include/asm/syscall_wrapper.h:20")),
                (
                    "__se_sys_read",
                    Some("arch/arm64/include/asm/syscall_wrapper.h:20, arch/x86/include/asm/syscall_wrapper.h:20")
                ),
                ("__do_sys_read", None),
                ("__arm64_sys_read", Some("arch/arm64/include/asm/syscall_wrapper.h:20")),
                (
                    "sys_read",
                    Some("include/linux/slab.h:10 (architectures without their own definition)")
                ),
            ]
        );
    }

    #[test]
    fn origin_distinguishes_definitions_in_the_same_file() {
        // include/linux/module.h defines module_init in both branches of
        // #ifndef MODULE; only the MODULE one defines __inittest.
        let module_h: Arc<str> = Arc::from("include/linux/module.h");
        let mk = |line: u32, body: &str, branch: u32| {
            Arc::new(MacroDef {
                params: vec!["fn".into()],
                variadic: None,
                body: body.into(),
                file: module_h.clone(),
                line,
                arch: None,
                branches: vec![(module_h.clone(), 3, branch)],
            })
        };
        let mut table: HashMap<String, Vec<Arc<MacroDef>>> = HashMap::new();
        table.insert(
            "module_init".into(),
            vec![
                mk(89, "__initcall(fn);", 0),
                mk(131, "static inline int __inittest(void) { return 0; }", 1),
            ],
        );
        let inv = Invocation {
            name: "module_init".into(),
            text: "module_init(foo_init)".into(),
            line: 5,
            followed_by_brace: false,
            conditions: vec![],
        };
        let g = generate(&table, &inv, &Arc::from("drivers/x.c"));
        assert_eq!(g.functions.len(), 1);
        assert_eq!(g.functions[0].origin.as_deref(), Some("include/linux/module.h:131"));
    }

    #[test]
    fn architecture_results_are_dropped_under_architecture_dependent_conditions() {
        let mut table: HashMap<String, Vec<Arc<MacroDef>>> = HashMap::new();
        table.insert(
            "DEF".into(),
            vec![def(&["n"], false, "WRAP(n) static long __se_sys##n(void) { }")],
        );
        table.insert(
            "WRAP".into(),
            vec![
                Arc::new(MacroDef {
                    params: vec!["n".into()],
                    variadic: None,
                    body: "long __x64_sys##n(void) { }".into(),
                    file: Arc::from("arch/x86/include/asm/syscall_wrapper.h"),
                    line: 20,
                    arch: Some(Arc::from("x86")),
                    branches: Vec::new(),
                }),
                def(&["n"], false, ""),
            ],
        );
        let names = |cond: Vec<extract::Cond>| {
            let inv = Invocation {
                name: "DEF".into(),
                text: "DEF(_truncate64)".into(),
                line: 3,
                followed_by_brace: false,
                conditions: cond,
            };
            let mut n: Vec<String> = generate(&table, &inv, &Arc::from("fs/open.c"))
                .functions
                .into_iter()
                .map(|f| f.name)
                .collect();
            n.sort();
            n
        };
        // #if BITS_PER_LONG == 32: only the architecture-neutral result.
        assert_eq!(
            names(vec![extract::Cond {
                block: 0,
                branch: 0,
                config_only: false
            }]),
            ["__se_sys_truncate64"]
        );
        // #ifdef CONFIG_COMPAT: both.
        assert_eq!(
            names(vec![extract::Cond {
                block: 0,
                branch: 0,
                config_only: true
            }]),
            ["__se_sys_truncate64", "__x64_sys_truncate64"]
        );
    }

    #[test]
    fn deps_detect_changed_definitions() {
        let mut table: HashMap<String, Vec<Arc<MacroDef>>> = HashMap::new();
        table.insert("GEN".into(), vec![def(&["n"], false, "int n##_fn(void) { }")]);
        let inv = Invocation {
            name: "GEN".into(),
            text: "GEN(foo)".into(),
            line: 7,
            followed_by_brace: false,
            conditions: vec![],
        };
        let g = generate(&table, &inv, &Arc::from("fs/read_write.c"));
        assert_eq!(
            g.functions
                .iter()
                .map(|f| (f.name.as_str(), f.line))
                .collect::<Vec<_>>(),
            [("foo_fn", 7)]
        );
        assert_eq!(g.functions[0].generated_by.as_deref(), Some("GEN(foo)"));
        assert!(g.deps.still_valid(&table));
        table.insert("GEN".into(), vec![def(&["n"], false, "int n##_other(void) { }")]);
        assert!(!g.deps.still_valid(&table));
    }
}
